//! Synthetic "songs" for the mastering tests: drums (kick, snare, hats as shaped noise and
//! swept sines), a bass line, chords, and a lead, arranged over a chord progression, with
//! per-genre tempo, levels, stereo spread, and spectral balance. Generated by code; no
//! binary fixtures.

#![allow(dead_code)]

use ferraus_core::ctx::Globals;
use ferraus_core::exec::{Invocation, Outcome, Runtime};
use ferraus_core::testing::{leak_registry, NO_PROGRESS, SIMPLE_IO};
use ferraus_core::{AudioBuffer, Registry};
use std::f64::consts::PI;
use std::path::Path;

pub fn registry() -> &'static Registry {
    use std::sync::OnceLock;
    static REG: OnceLock<&'static Registry> = OnceLock::new();
    REG.get_or_init(|| {
        let mut ops = Vec::new();
        ops.extend(ferraus_dsp::ops());
        ops.extend(ferraus_analysis::ops());
        ops.extend(ferraus_edit::ops());
        ops.extend(ferraus_pitch::ops());
        ops.extend(ferraus_master::ops());
        leak_registry(ops)
    })
}

pub fn invoke(command: &str, inputs: &[&Path], args: &[(&str, &str)], output: Option<&Path>) -> Outcome {
    let rt = Runtime {
        registry: registry(),
        io: &SIMPLE_IO,
        progress: &NO_PROGRESS,
        presets: &|_, _| None,
        cancel: Default::default(),
    };
    let globals = Globals {
        output: output.map(|p| p.display().to_string()),
        overwrite: true,
        sidecar: false,
        ..Default::default()
    };
    rt.invoke(Invocation {
        command: command.into(),
        args: args.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect(),
        inputs: inputs.iter().map(|p| p.display().to_string()).collect(),
        globals,
        argv: vec![],
        stdin: None,
    })
}

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> f64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        (self.0 >> 11) as f64 / (1u64 << 53) as f64 * 2.0 - 1.0
    }
}

/// Arrangement and balance of one synthetic song.
#[derive(Clone, Debug)]
pub struct Style {
    pub name: &'static str,
    pub sr: u32,
    pub secs: f64,
    pub bpm: f64,
    /// Linear levels.
    pub kick: f64,
    pub snare: f64,
    pub hats: f64,
    pub bass: f64,
    pub chords: f64,
    pub lead: f64,
    /// Harmonic richness of chords and lead (0 = sines, 1 = bright saw-like).
    pub bright: f64,
    /// Stereo spread of the chords (0 = mono, 1 = wide).
    pub spread: f64,
    /// Overall gain applied at the end (dB).
    pub gain_db: f64,
    pub seed: u64,
}

