fn midi_hz(n: f64) -> f64 {
    440.0 * 2f64.powf((n - 69.0) / 12.0)
}

/// A tone with `bright`-controlled harmonics (1/k amplitude, up to 8 harmonics).
fn tone(phase: f64, bright: f64) -> f64 {
    let mut v = phase.sin();
    let mut norm = 1.0;
    for k in 2..=8 {
        let a = bright.powf(0.7) / k as f64;
        v += a * (k as f64 * phase).sin();
        norm += a;
    }
    v / norm.sqrt()
}

pub fn song(s: &Style) -> AudioBuffer {
    let sr = s.sr as f64;
    let n = (s.secs * sr) as usize;
    let mut l = vec![0.0f64; n];
    let mut r = vec![0.0f64; n];
    let mut rng = Rng(s.seed.wrapping_mul(0x9E3779B97F4A7C15) | 1);
    let beat = 60.0 / s.bpm;
    // progression: I - vi - IV - V in C (roots as MIDI), 2 s per chord
    let prog: [(f64, [f64; 3]); 4] = [
        (48.0, [60.0, 64.0, 67.0]),
        (45.0, [57.0, 60.0, 64.0]),
        (41.0, [57.0, 60.0, 65.0]),
        (43.0, [59.0, 62.0, 67.0]),
    ];
    let melody = [72.0, 74.0, 76.0, 79.0, 76.0, 74.0, 72.0, 69.0];
    let mut lp_state = 0.0f64;
    let mut snare_lp = 0.0f64;
    for i in 0..n {
        let t = i as f64 / sr;
        let bpos = t / beat;
        let bi = bpos.floor();
        let bt = (bpos - bi) * beat; // seconds since the beat
        let chord = prog[((t / 2.0) as usize) % 4];
        let mut mono = 0.0;
        // kick: every beat, swept sine
        if s.kick > 0.0 {
            let f = 50.0 + 70.0 * (-bt * 30.0).exp();
            let ph = 2.0 * PI * (50.0 * bt + 70.0 / 30.0 * (1.0 - (-bt * 30.0).exp()));
            let _ = f;
            mono += s.kick * ph.sin() * (-bt * 9.0).exp();
        }
        // snare: beats 2 and 4, filtered noise + body
        let noise = rng.next();
        if s.snare > 0.0 && (bi as i64) % 2 == 1 {
            snare_lp += 0.5 * (noise - snare_lp);
            mono += s.snare * (0.7 * snare_lp + 0.3 * (2.0 * PI * 190.0 * bt).sin()) * (-bt * 18.0).exp();
        }
        // hats: every eighth, high-passed noise, slightly right
        let mut hat = 0.0;
        if s.hats > 0.0 {
            let et = ((bpos * 2.0) - (bpos * 2.0).floor()) * beat / 2.0;
            let hp_state = noise - lp_state;
            lp_state += 0.6 * (noise - lp_state);
            hat = s.hats * hp_state * (-et * 60.0).exp();
        }
        // bass: root, eighth-note pulses
        let et = ((bpos * 2.0) - (bpos * 2.0).floor()) * beat / 2.0;
        let bass = s.bass * tone(2.0 * PI * midi_hz(chord.0) * t, 0.3) * (0.55 + 0.45 * (-et * 6.0).exp());
        mono += bass;
        // lead: one melody note per beat, centred
        let note = melody[(bi as usize) % melody.len()];
        let lead = s.lead * tone(2.0 * PI * midi_hz(note) * t, s.bright) * (0.4 + 0.6 * (-bt * 4.0).exp());
        mono += lead;
        // chords: wide (different detune per side)
        let (mut cl, mut cr) = (0.0, 0.0);
        for (k, nn) in chord.1.iter().enumerate() {
            let f = midi_hz(*nn);
            let det = 1.0 + 0.002 * s.spread * (k as f64 + 1.0);
            cl += tone(2.0 * PI * f * t, s.bright);
            cr += tone(2.0 * PI * f * det * t + s.spread * (k as f64 + 0.5), s.bright);
        }
        let ca = s.chords / 3.0;
        l[i] = mono + hat * 0.8 + ca * cl;
        r[i] = mono + hat * 1.0 + ca * cr;
    }
    let g = 10f64.powf(s.gain_db / 20.0);
    // short fades so edges are clean
    let fade = (0.01 * sr) as usize;
    let data = vec![l, r]
        .into_iter()
        .map(|c| {
            c.iter()
                .enumerate()
                .map(|(i, v)| {
                    let f = (i.min(n - 1 - i) as f64 / fade as f64).min(1.0);
                    (v * g * f) as f32
                })
                .collect()
        })
        .collect();
    AudioBuffer::from_planar(s.sr, data)
}

pub fn write(path: &Path, b: &AudioBuffer) {
    ferraus_core::testing::write_wav(path, b);
}
